var i=`0179-pappa-al-pomodoro`;var a=`world-0179`;var n=`IT`;var o=`southern-europe`;var s=4;var r=51;var l={en:`Pappa al Pomodoro`,ua:`Паппа аль помодоро`};var d={en:`A classic dish from Italy, featuring garlic, tomato, white bread, basil. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Італія. Основні складники: часник, помідор, білий хліб, базилік. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var g=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 8 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 8 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:8,i:[[`garlic`,4,`clove`],[`extra-virgin-olive-oil`,55,`ml`]]},{en:`Add the listed ingredients to the pot. Keep at a gentle simmer for about 25 minutes, until tender and cooked through.`,ua:`Додайте зазначені складники до каструлі. Варіть за слабкого кипіння приблизно 25 хвилин до м’якості та готовності.`,t:[`simmering`],m:25,i:[[`tomato`,850,`g`],[`tomato-passata`,280,`g`],[`vegetable-stock`,550,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 15 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 15 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:15,i:[[`white-bread`,280,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`basil`,25,`g`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]}];var m={slug:i,id:a,country:`IT`,region:o,servings:4,minutes:51,title:l,text:d,steps:g};export{n as country,m as default,a as id,r as minutes,o as region,s as servings,i as slug,g as steps,d as text,l as title};